    for i, num in enumerate(nums):
      if i > maxRight:
        # Start a new partition that starts from nums[i].
        # Each partition doubles the total number of good partitions.
        ans = ans * 2 % MOD
      maxRight = max(maxRight, lastSeen[num])

    return ans

